#!/bin/bash
# Claude Fable 5.2 (low effort) vet-and-fix pass via the claude CLI.
# Usage: bash ppk-dhanya/fable_review.sh FIRST LAST ["extra notes"]
cd "$(dirname "$0")"
printf '%s' "You are a Malayalam script editor. Vet and fix ep$1.txt … ep$2.txt in this folder (edit only those). Read BIBLE.md and the approved ep6.txt–ep8.txt for style; story source is ../ppk-v5/src_epN.txt (every beat present, in order, same cliffhanger). Read each episode end to end. Fix only real problems: spelling/grammar/case errors, lines a Kerala speaker would not say, back-to-back dialogue with no narration between speakers, inline quotes buried in narration (make them their own dialogue paragraphs), inserted paragraphs that break a sequence, missing client beats, contradictions, scene jumps. Antony's full name is ആന്റണി സിമേതി and his company സിമേതി ഗ്രൂപ്പ് (never ആന്റണി മാത്യു); Piyush is പവന്‍. Where an episode is under 600 words, add a little scene or character description (no new plot). Keep the format (single-quote dialogue paragraphs, '..', no Latin letters/digits/double quotes) and 580–850 words. $3 Then run: python3 tools.py normalize $1 $2 && python3 tools.py check $1 $2 and fix until clean. Reply with a short list of fixes per episode." \
| claude -p --model claude-fable-5-2 --effort low --allowedTools "Read,Edit,Bash(python3 tools.py *)"
